codeExamples.code:
let score = 100;
score += 50;    // score is now 150
console.log(score);

score -= 20;    // score is now 130
console.log(score);

score *= 2;     // score is now 260
console.log(score);

score /= 4;     // score is now 65
console.log(score);

score %= 10;    // score is now 5 (remainder of 65 / 10)
console.log(score);

let isLoggedIn = true;
let isAdmin = false;

console.log(isLoggedIn && isAdmin);   // false (both must be true)
console.log(isLoggedIn || isAdmin);   // true  (at least one is true)
console.log(!isLoggedIn);             // false (flips true to false)
console.log(!isAdmin);                // true  (flips false to true)

let score = 0;
let name = "";
let count = null;

// || treats 0 and "" as falsy — not what we want
console.log(score || 100);    // 100 (0 replaced!)
console.log(name || "Guest"); // "Guest" ("" replaced!)

// ?? only treats null and undefined as empty
console.log(score ?? 100);    // 0   (keeps 0)
console.log(name ?? "Guest"); // ""  (keeps empty string)
console.log(count ?? 100);   // 100 (null triggers default)

let user = {
  name: "Alex",
  address: {
    city: "London"
  }
};

let stranger = { name: "Sam" };

// Without optional chaining — this would crash
// console.log(stranger.address.city);  // TypeError!

// With optional chaining — safe
console.log(user.address?.city);     // "London"
console.log(stranger.address?.city); // undefined (no error!)
console.log(stranger.address?.zip?.code); // undefined (safe nested access)

// Optional chaining with methods
console.log(user.getName?.());       // undefined (method doesn't exist)
console.log(user.name?.toUpperCase?.()); // "ALEX"

// ||= sets a default when the variable is falsy
let theme = "";
theme ||= "dark";
console.log(theme);  // "dark" (empty string is falsy)

let count = 0;
count ||= 10;
console.log(count);  // 10 (0 is falsy — maybe not what you want!)

// ??= sets a default only for null/undefined
let fontSize = 0;
fontSize ??= 16;
console.log(fontSize);  // 0 (keeps 0 because it's not null/undefined)

let color;
color ??= "blue";
console.log(color);  // "blue" (undefined triggers default)

let username = "Vishnu";
let isAdmin = false;

// &&= only assigns if the left side is truthy
username &&= username.toUpperCase();
console.log(username);  // "VISHNU" (was truthy, so it updated)

isAdmin &&= "admin";
console.log(isAdmin);  // false (was falsy, so it kept the original)

// Useful pattern: only modify if the value exists
let input = null;
input &&= input.trim();
console.log(input);  // null (was null, so no update happened)

// Simulating user input (always comes as strings)
let input = "42";

// Without conversion — string concatenation!
console.log(input + 8);   // "428" (wrong!)

// With explicit conversion — math works!
let num = Number(input);
console.log(num + 8);     // 50 (correct!)

// Invalid input gives NaN
let bad = Number("hello");
console.log(bad);         // NaN
console.log(isNaN(bad));  // true

// Converting to strings
let price = 19.99;
let tag = String(price);
console.log(tag);          // "19.99"
console.log(typeof tag);   // "string"

// Converting to booleans
let emptyName = "";
let hasName = Boolean(emptyName);
console.log(hasName);      // false (empty string is falsy)

let score = 0;
let hasScore = Boolean(score);
console.log(hasScore);     // false (0 is falsy)

let items = [1, 2, 3];
let hasItems = Boolean(items);
console.log(hasItems);     // true (arrays are truthy!)
